def _vjs(value: Any) -> str:
    # JSON encoding for scalars (ids, kinds, hex64 strings, timestamps).
    return json.dumps(value, ensure_ascii=False)


# Sentinels tagging container and ambiguous-scalar kinds inside value keys.
# They are plain objects, so they can never equal a string, number, or other
# payload value; identity and hash are stable within the process, which is
# all a per-call engine registry needs.
_VKEY_BOOL = object()
_VKEY_FLOAT = object()
_VKEY_LIST = object()
_VKEY_TUPLE = object()
_VKEY_DICT = object()
_VKEY_OTHER = object()


def _vtype_key(value: Any) -> Any:
    """Type-faithful, sortable identity of a dict key (or other hashable).

    Every identity is a tag-first tuple, so identities of differently typed
    keys always order and compare without ``TypeError`` — an integer fact
    key never merges with or mis-sorts against the string with the same
    digits, and a tuple key never merges with anything else.  Used only for
    dict keys, which need a deterministic order; values use
    :func:`_vvalue_key`.
    """
    if isinstance(value, str):
        return ("s", value)
    if isinstance(value, bool):
        return ("b", value)
    if isinstance(value, int):
        return ("i", value)
    if isinstance(value, float):
        return ("f", value)
    if value is None:
        return ("n",)
    if isinstance(value, tuple):
        return ("t", tuple(_vtype_key(item) for item in value))
    return ("o", type(value).__qualname__, repr(value))


def _vvalue_key(value: Any) -> Any:
    """Type-faithful structural identity of a leaf credential value.

    The reuse registry must never merge values whose compact JSON text
    merely *looks* equal while their Python types differ: an integer fact
    or condition key and the string with the same digits, a tuple and the
    list with the same items, ``True`` and ``1``.  This key walks the
    value once and records the real type of every container and key, so
    only values equal in both type and value share an identity; anything
    else falls through to full validation, which rejects it.  Strings and
    ints map to themselves (they cannot collide with any other type's
    identity); containers, bools, floats, and exotica are tagged with
    sentinels that no payload value can equal.  Dict item order is
    normalized away by sorting on the (type-tagged) keys, and every legal
    credential contains only dicts, lists, strings, bools, ints, and
    nulls, for which the key is exact.  This is a structural walk, not a
    serialization: no text or byte form of the value is produced for
    keying.
    """
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        # Fast path: a string key is its own identity (no other key type
        # maps to a plain string, and plain strings sort unambiguously), so
        # the common all-string-key dict skips the per-key type tagging.
        items = []
        for key, item in value.items():
            if not isinstance(key, str):
                items = None
                break
            items.append((key, _vvalue_key(item)))
        if items is None:
            items = [
                (_vtype_key(key), _vvalue_key(item))
                for key, item in value.items()
            ]
        items.sort()
        return (_VKEY_DICT, tuple(items))
    if isinstance(value, list):
        return (_VKEY_LIST, tuple([_vvalue_key(item) for item in value]))
    if value is None:
        return None
    if isinstance(value, bool):
        return (_VKEY_BOOL, value)
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return (_VKEY_FLOAT, value)
    if isinstance(value, tuple):
        return (_VKEY_TUPLE, tuple([_vvalue_key(item) for item in value]))
    return (_VKEY_OTHER, type(value).__qualname__, repr(value))


class _CanonicalDict(dict):
    """A plain dict carrying the root of a canonical generator result.

    It behaves exactly like a plain ``dict`` in every respect — it *is* one:
    equality, ordering, iteration, JSON encoding, and ``isinstance`` checks
    are unchanged.  The only addition is a ``__deepcopy__`` that rebuilds
    the independent copy through the canonical compact JSON form, which is
    far cheaper than the generic recursive copier for the very large
    credential trees these functions return.  The copy is again a
    ``_CanonicalDict`` (so repeated copies stay on the fast path) over plain
    dicts and lists, so nothing beyond copying speed is observable, and the
    copy remains fully independent of the original at every level.
    """

    def __deepcopy__(self, memo: dict) -> Any:
        clone = _CanonicalDict(
            json.loads(json.dumps(self, ensure_ascii=False, separators=(",", ":")))
        )
        memo[id(self)] = clone
        return clone


def _emit(canonical_json: str) -> dict[str, Any]:
    """Materialize a canonical JSON document as an independent result tree."""
    return _CanonicalDict(json.loads(canonical_json))


class _VKey:
    """A hash-consed composite value key.

    Composite nodes (bundles, diffs, proofs) key their registries by tuples
    of scalar fields plus their children's keys.  Plain tuples re-hash the
    whole nested structure on every lookup; wrapping the tuple caches the
    hash once, so a repeat occurrence resolves in O(1).  Equality still
    compares the full underlying tuple, so distinct values can never merge.
    """

    __slots__ = ("parts", "_hash")

    def __init__(self, parts: Any) -> None:
        self.parts = parts
        self._hash = hash(parts)

    def __hash__(self) -> int:
        return self._hash

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, _VKey):
            return NotImplemented
        return self.parts == other.parts


class _VNode:
    __slots__ = (
        "key", "canonical", "json", "sem", "semkey", "dsem", "dsemkey",
        "truth", "complete",
        "root", "root_after", "members", "before_node", "after_node",
        "digest", "stage_parts",
    )

    def __init__(self) -> None:
        self.key: Any = None
        self.canonical: Any = None
        self.json: str = ""
        self.sem: Any = None
        self.semkey: Any = None
        self.dsem: Any = None
        self.dsemkey: Any = None
        self.truth: bool = False
        self.complete: bool = True
        self.root: str = ""
        self.root_after: str = ""
        self.members: list[Any] = []
        self.before_node: Any = None
        self.after_node: Any = None
        self.digest: str = ""
        self.stage_parts: list[str] = []


class _VEngine:
    def __init__(self) -> None:
        self.cred: dict[str, _VNode] = {}
        self.mbundle: dict[Any, _VNode] = {}
        self.mdiff: dict[Any, _VNode] = {}
        self.p0: dict[Any, _VNode] = {}
        self.b0: dict[Any, _VNode] = {}
        self.d0: dict[Any, _VNode] = {}
        self.p1: dict[Any, _VNode] = {}
        self.b1: dict[Any, _VNode] = {}
        self.d1: dict[Any, _VNode] = {}
        self.p2: dict[Any, _VNode] = {}
        self.b2: dict[Any, _VNode] = {}
        self.d2: dict[Any, _VNode] = {}
        self.p3: dict[Any, _VNode] = {}
        self.b3: dict[Any, _VNode] = {}
        self.d3: dict[Any, _VNode] = {}
        # Generated diffs are fully determined by the two side nodes and the
        # derived change entries; memoizing on those avoids rebuilding the
        # whole five-item payload (and its SHA-256) for a repeated pair.
        self.gen: dict[Any, _VNode] = {}
        # Format checks are pure in the input string, so a validated
        # timestamp or hex64 summary is remembered for the life of the
        # engine (one top-level call) instead of being re-checked at every
        # occurrence.
        self.times: dict[str, str] = {}
        self.hexes: dict[str, str] = {}

    def _time(self, value: Any, field: str) -> str:
        if isinstance(value, str):
            cached = self.times.get(value)
            if cached is not None:
                return cached
        checked = _check_time(value, field)
        self.times[checked] = checked
        return checked

    def _hex64(self, value: Any, field: str) -> str:
        if isinstance(value, str):
            cached = self.hexes.get(value)
            if cached is not None:
                return cached
        checked = _check_hex64(value, field)
        self.hexes[checked] = checked
        return checked

    # ------------------------------------------------------------ leaf cred
    def credential(self, value: Any, field: str) -> _VNode:
        if not isinstance(value, dict):
            raise ValueError(f"{field} must be a credential dict")
        # The reuse identity is a type-faithful structural key, not JSON
        # text: it records the real type of every container and key, so a
        # value that merely serializes like an already-seen credential (an
        # integer fact or condition key where the same digits were verified
        # as a string, a tuple where a list is required) never reuses that
